import heapq
from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Priority queue to store (current value, current position, remaining steps)
    pq = []
    for i in range(N):
        for j in range(N):
            heapq.heappush(pq, (grid[i][j], (i, j), k-1))

    while pq:
        value, (x, y), steps = heapq.heappop(pq)
        if steps == 0:
            return [value]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                heapq.heappush(pq, (grid[nx][ny], (nx, ny), steps-1))

    return []
