def is_samepatterns(colors, patterns):
    # Dictionary to store the mapping from pattern to color
    pattern_to_color = {}
    # Set to store unique colors
    used_colors = set()

    for color, pattern in zip(colors, patterns):
        if pattern not in pattern_to_color:
            # If the pattern is new, check if the color has been used before
            if color in used_colors:
                return False
            # Assign the new pattern to the color and mark the color as used
            pattern_to_color[pattern] = color
            used_colors.add(color)
        else:
            # If the pattern is already in the dictionary, check if it maps to the same color
            if pattern_to_color[pattern] != color:
                return False

    return True
