def max_product(arr):
    n = len(arr)
    # Initialize the list to store the maximum product subsequence at each index
    mp = [0] * n
    # The maximum product subsequence at any index is at least the number itself
    for i in range(n):
        mp[i] = arr[i]

    # Iterate through the array
    for i in range(1, n):
        for j in range(i):
            # Check if arr[i] can form an increasing subsequence with arr[j]
            if arr[i] % arr[j] == 0 and mp[i] < mp[j] * arr[i]:
                mp[i] = mp[j] * arr[i]

    # The maximum product subsequence is the maximum value in mp
    return max(mp)
```

