def jacobsthal_num(n): 
    # Base cases for the first two Jacobsthal numbers
    if n == 0: 
        return 0
    if n == 1: 
        return 1
    # Recursive relation for Jacobsthal numbers
    return jacobsthal_num(n - 1) + 2 * jacobsthal_num(n - 2) 
