def check_expression(expression):
    brackets = {"(": ")", "{": "}", "[": "]"}
    stack = []
    for char in expression:
        if char in brackets.keys():
            stack.append(char)
        elif char in brackets.values():
            if not stack or brackets[stack.pop()] != char:
                return False
    return not stack
